  height: 24px; }
.h-32 { font-size: 8px;
  line-height: 32px;
  height: 32px; }
.h-40 { font-size: 8px;
  line-height: 40px;
  height: 40px; }
.left-block { display: inline-block;
  width: 49%;
  vertical-align: top; }
@media screen and (max-width: 600px) {
  .left-block { float: none !important;
